package com.bank.pacelc.model;

import java.util.concurrent.atomic.AtomicReference;

public class Replica {
    public final String name;
    private final AtomicReference<String> value = new AtomicReference<>("<empty>");
    public Replica(String name) { this.name = name; }
    // Simulate replication lag for async (EL) propagation.
    public void applyAsync(String v, long lagMs) {
        new Thread(() -> { sleep(lagMs); value.set(v); }).start();
    }
    public void applySync(String v) { value.set(v); } // immediate ack path (EC)
    public String read() { return value.get(); }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException ignored) {} }
}
