package com.bank.pacelc.service;

import com.bank.pacelc.model.Replica;
import java.util.List;
import java.util.logging.Logger;

public class ReplicatedStore {
    private static final Logger log = Logger.getLogger(ReplicatedStore.class.getName());
    public enum Level { ONE, QUORUM }   // EL vs EC
    private final List<Replica> replicas;
    public ReplicatedStore(List<Replica> replicas) { this.replicas = replicas; }

    public long write(String value, Level level) {
        long start = System.currentTimeMillis();
        if (level == Level.QUORUM) {
            // EC: wait for a quorum to apply synchronously → slower, but reads are correct.
            int quorum = replicas.size() / 2 + 1;
            for (int i = 0; i < quorum; i++) replicas.get(i).applySync(value);
            // remaining replicas catch up async
            for (int i = quorum; i < replicas.size(); i++) replicas.get(i).applyAsync(value, 50);
            log.info(() -> "EC write (QUORUM) acked after majority applied");
        } else {
            // EL: ack after ONE local replica, others async → fast, possibly stale reads.
            replicas.get(0).applySync(value);
            for (int i = 1; i < replicas.size(); i++) replicas.get(i).applyAsync(value, 80);
            log.info(() -> "EL write (ONE) acked after single replica");
        }
        return System.currentTimeMillis() - start;
    }

    public String readFrom(int replicaIndex) { return replicas.get(replicaIndex).read(); }
}
