package com.bank.pacelc;

import com.bank.pacelc.model.Replica;
import com.bank.pacelc.service.ReplicatedStore;
import java.util.List;

public class PacelcApplication {
    public static void main(String[] args) throws InterruptedException {
        List<Replica> replicas = List.of(new Replica("r1"), new Replica("r2"), new Replica("r3"));
        ReplicatedStore store = new ReplicatedStore(replicas);

        // Balance write → EC (QUORUM): consistent, read-after-write is correct everywhere soon.
        long ecLatency = store.write("balance=50000", ReplicatedStore.Level.QUORUM);
        System.out.println("EC (balance) latency=" + ecLatency + "ms, read r2=" + store.readFrom(1));

        // Feed write → EL (ONE): fast, but a read from a lagging replica may be stale.
        long elLatency = store.write("feed=login", ReplicatedStore.Level.ONE);
        System.out.println("EL (feed) latency=" + elLatency + "ms, read r3 (maybe stale)=" + store.readFrom(2));
        Thread.sleep(150);
        System.out.println("EL (feed) read r3 after lag catches up=" + store.readFrom(2));
    }
}
